from pathlib import Path
import json,collections,re,hashlib
from urllib.parse import quote
R=Path(__file__).resolve().parents[1];D=R.parent;O=R/'documentation-audit'
read=lambda p:json.loads(p.read_text(encoding='utf-8'))
assert read(O/'progress.json')['completed_roots']==read(O/'progress.json')['total_roots'],'Discovery is incomplete'
units=read(O/'location-inventory.json');by={x['path']:x for x in units};decisions=read(O/'manual-decisions.json')
for change in decisions:
 if change['path'] in by:by[change['path']].update({k:v for k,v in change.items() if k!='path'})
pairs=read(O/'duplicate-source-review.json');parent={p:p for p in by}
def find(p):
 while parent[p]!=p:parent[p]=parent[parent[p]];p=parent[p]
 return p
for pair in pairs:
 a,b=pair['paths']
 if pair['decision']=='group-copy-family' and a in by and b in by and not by[a]['status'].startswith('Excluded') and not by[b]['status'].startswith('Excluded'):parent[find(b)]=find(a)
groups=collections.defaultdict(list)
for u in units:groups[find(u['path'])].append(u)
evidence={x['project']:x for x in read(O/'representative-evidence.json')}
statusOrder={'Substantially enhanced':4,'Partially enhanced':3,'Minimal documentation':2,'Not enhanced':1,'Unclear — needs manual review':0}
projects=[];excluded=[]
for group in groups.values():
 legitimate=[u for u in group if not u['status'].startswith('Excluded')]
 if not legitimate:
  excluded.extend({'path':u['path'],'absolutePath':u['absolutePath'],'reason':u.get('reason',u['status'])} for u in group);continue
 u=max(legitimate,key=lambda x:(statusOrder.get(x['status'],0),x['learningWords'],x['learningDocumentCount'],x['score'],not x['path'].startswith('geminiorganized/')))
 ev=evidence.get(u['path'],{}).get('documents',[])
 row={k:u[k] for k in ['path','absolutePath','name','summary','status','rating','score','sourceFiles','sourceBytes','complexitySourceFiles','documentCount','documentWords','learningDocumentCount','learningWords','dimensionDocuments','learningRoots']}
 row['id']=hashlib.sha256(u['path'].encode()).hexdigest()[:12];row['locations']=[{'path':x['path'],'absolutePath':x['absolutePath'],'status':x['status'],'learningDocuments':x['learningDocumentCount'],'learningWords':x['learningWords']} for x in group]
 row['evidence']=ev;row['components']=[{'path':x['path'],'markers':x['markers']} for x in u['components'] if x['markers']];row['notes']=[u[k] for k in ['reason','countingNote'] if u.get(k)]
 if u.get('selectionReason'):row['selectionReason']=u['selectionReason']
 row['approxSize']=('Very large' if u['complexitySourceFiles']>=2000 else 'Large' if u['complexitySourceFiles']>=400 else 'Medium' if u['complexitySourceFiles']>=80 else 'Small')+f' ({u["sourceFiles"]:,} source files; {u["sourceBytes"]/1e6:.1f} MB)'
 projects.append(row)
enhanced=sorted([x for x in projects if x['status']=='Substantially enhanced'],key=lambda x:x['score'],reverse=True)
partial=sorted([x for x in projects if x['status']=='Partially enhanced'],key=lambda x:x['path'].lower())
remaining=sorted([x for x in projects if x['status'] in ['Not enhanced','Minimal documentation']],key=lambda x:x['path'].lower())
unclear=[x for x in projects if x['status']=='Unclear — needs manual review']
selection=read(O/'ranked-selection.json') if (O/'ranked-selection.json').exists() else [x['path'] for x in enhanced[:50]]
mapping={x['path']:x for x in projects};top=[mapping[p] for p in selection];assert len(top)<=50 and all(x['status']=='Substantially enhanced' for x in top)
for rank,x in enumerate(top,1):x['rank']=rank
nextbatch=read(O/'next-batch.json');assert len(nextbatch)==10
for item in nextbatch:
 assert item['path'] in mapping and mapping[item['path']]['status']!='Substantially enhanced',item
 item.update({'absolutePath':mapping[item['path']]['absolutePath'],'status':mapping[item['path']]['status'],'evidence':mapping[item['path']]['evidence'][:2]})
scan=read(O/'scan-manifest.json');summary={'totalLegitimateProjects':len(projects),'alreadySubstantiallyEnhanced':len(enhanced),'partiallyEnhanced':len(partial),'notYetEnhanced':len(remaining),'unclearRequiresManualReview':len(unclear),'topProjectsSelected':len(top),'remainingFullTreatment':len(partial)+len(remaining),'unresolvedAdditionalCandidates':len(unclear),'physicalLocationsReviewed':len(units),'legitimatePhysicalLocations':sum(len(x['locations']) for x in projects),'duplicateLocationsCollapsed':sum(len(x['locations'])-1 for x in projects),'excludedLocations':len(excluded),'organizedPhysicalLocations':sum(x['path'].startswith('_Organized Desktop/') for x in units),'textDocumentsRead':read(O/'progress.json')['text_documents_read'],'scanErrors':read(O/'progress.json')['errors']}
assert len(projects)==len(enhanced)+len(partial)+len(remaining)+len(unclear)
result={'schemaVersion':1,'scope':str(D),'auditStarted':scan['started'],'auditCompleted':scan['completed'],'method':'Read-only current filesystem discovery; textual content screening, representative-document review, sampled source comparison and explicit project-family accounting. No installs, project edits, tests or runtimes executed.','countingPolicy':'One maintained application or coherent learning workspace per record. Client/server/packages and nested exercises stay within their parent. Independent nested products are separated. Source-matching copies are grouped; materially different implementations remain related records.','summary':summary,'topProjects':top,'enhancedProjects':enhanced,'partiallyEnhancedProjects':partial,'remainingProjects':remaining,'duplicatesOrVariants':pairs,'manualReview':unclear,'recommendedNextBatch':nextbatch,'excludedLocations':excluded,'coverageEvidence':'documentation-audit/scan-manifest.json','locationInventory':'documentation-audit/location-inventory.json'}
sampledocs=[d for x in evidence.values() for d in x['documents']]
checks=[{'document':d['path'],**c} for d in sampledocs for c in d['localLinkChecks'] if '(' not in c['target'] and ')' not in c['target']]
missing=[c for c in checks if not c['exists']]
quality={'representativeDocumentsRead':len(sampledocs),'documentsChangedSinceScan':sum(d['changedSinceScan'] for d in sampledocs),'simpleLocalFileLinksChecked':len(checks),'nonResolvingSimpleLocalFileLinks':len(missing),'method':'Up to 20 local Markdown targets per representative file; excludes targets with parentheses to avoid ambiguous parsing. Checks file existence, not line/heading correctness. Counts include copy locations.','examples':[]}
for key in ['mastersaleorPY','masteropenedxPYJS','netopen5']:
 quality['examples'].extend([c for c in missing if key in c['document']][:2])
result['documentationQualityReview']=quality
result['rankingMethod']='Full-text screening signals support discovery; the top order is an editorial judgment from source-specific explanations, exercises, onboarding, application complexity and breadth. The numeric score is a screening aid, not a quality certification or strict sort key.'
(R/'project-audit.json').write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf-8')
link=lambda p:quote('../'+p,safe='/+')
def docs(x,limit=2):
 def title(d):
  heads=d.get('headings',[])
  return re.sub(r'^#+\s*','',heads[0]).replace('|','/').replace('[','').replace(']','')[:75] if heads else Path(d['path']).name
 return '; '.join(f'[{title(d)}]({link(d["path"])})' for d in x['evidence'][:limit]) or 'No substantial explanatory files verified'
def clean(s):return str(s).replace('|','/').replace('\n',' ')
lines=['# Project documentation and upskilling audit','','Audited September 8, 2026 (America/Los_Angeles). Scope: the full Desktop, including `_Organized Desktop` and `geminiorganized`. Only audit artifacts were written; no project was modified.','','## Audit summary','','| Accounting category | Projects |','|---|---:|',f'| Total legitimate projects discovered | {len(projects)} |',f'| Already substantially enhanced | {len(enhanced)} |',f'| Partially enhanced | {len(partial)} |',f'| Not yet enhanced, including minimal documentation | {len(remaining)} |',f'| Unclear / requires manual review | {len(unclear)} |',f'| Top projects selected | {len(top)} |','',f'**Remaining projects that still need the full documentation/upskilling treatment: {summary["remainingFullTreatment"]}.**','',f'That is {len(partial)} partially enhanced + {len(remaining)} not enhanced/minimally documented. '+(f'An additional {len(unclear)} unresolved candidates require review before assigning treatment.' if unclear else 'There are no unresolved documentation classifications.'),'',f'Accounting: {len(projects)} = {len(enhanced)} enhanced + {len(partial)} partial + {len(remaining)} not yet enhanced + {len(unclear)} unclear.','','## Scope, evidence and counting rules','',f'- Reviewed **{len(units)} physical locations**, including **{summary["organizedPhysicalLocations"]} in `_Organized Desktop`**. Current discovery covered all 98 top-level folders in scope and read {summary["textDocumentsRead"]:,} text documents; {summary["scanErrors"]} filesystem read errors were recorded.',f'- Collapsed **{summary["duplicateLocationsCollapsed"]} duplicate/copy locations**. Excluded **{len(excluded)}** reference-only, empty, generated or clearly trivial locations; reasons are retained in JSON.', '- Counted coherent learning workspaces such as JS1, newcodexJS and newcodex3 once, while inspecting their nested applications. A frontend, API, worker or shared package is not an extra unrelated project. Four independent products nested inside the organized Job Tracker folder are separate records.', '- The earlier “75 projects improved” report counted implementation targets. This audit uses application/workspace families, so its denominator deliberately differs from that historical batch count.', '- Classification uses documentation content: onboarding, concrete architecture/flows, explanations and tradeoffs, hands-on progression, and engineering workflow. File names and word counts are discovery aids. Translations, repeated text and generated copies do not earn extra learning-depth credit.', '- High/Exceptional means a substantial learning system is present. It does not certify every claim, setup command, historical line number, external PR review or exercise. Existing tests and apps were not run for this read-only audit. Source sizes include tests and styles and are approximate complexity signals.', '- Copy groups are based on current source comparisons, with deterministic samples for larger locations, plus known relationships. Grouping means the same project family, not byte-identical complete trees. Different documentation at alternate locations is recorded per location.', '', '## Top learning projects','','Ranked by depth and onboarding first, followed by application complexity, architecture, engineering breadth and hands-on value. These are the strongest selected projects, not the complete enhanced inventory.','','| Rank | Project | Location | Project Summary | Docs / Learning Content | Why It Qualifies | Learning Depth |','|---:|---|---|---|---|---|---|']
for x in top:
 why=x.get('selectionReason') or ('Concrete codebase/architecture explanations, progressive exercises and engineering review/debugging material; '+str(x['learningDocumentCount'])+' substantive learning/architecture documents screened.')
 lines.append(f'| {x["rank"]} | {clean(x["name"])} | [{clean(x["path"])}]({link(x["path"])}) | {clean(x["summary"])} | {docs(x,3)} | {clean(why)} | **{x["rating"]}** |')
lines+=['','## Remaining projects — not yet fully enhanced','','This inventory includes partial, minimal, missing and unresolved documentation. Projects below the top-50 cutoff that already have substantial learning systems are not put into this backlog.','','| # | Project | Location | Approx. Size | Existing Docs | Enhancement Status |','|---:|---|---|---|---|---|']
for i,x in enumerate(sorted(partial+remaining+unclear,key=lambda x:x['path'].lower()),1):lines.append(f'| {i} | {clean(x["name"])} | [{clean(x["path"])}]({link(x["path"])}) | {x["approxSize"]} | {x["documentCount"]} text files; {docs(x)} | {x["status"]} |')
lines+=['','## Recommended next 10','','These fill different engineering gaps. They are recommendations only; no missing documentation or code was generated.','','| # | Project | What the upgrade should teach |','|---:|---|---|']
for i,x in enumerate(nextbatch,1):lines.append(f'| {i} | [{x["path"]}]({link(x["path"])}) | {clean(x["reason"])} |')
lines+=['','## Other substantially enhanced projects','','These already qualify but fall outside the selected top list. They are not unfinished just because they are absent from the top 50.','']
for x in enhanced:
 if x not in top:lines.append(f'- [{x["path"]}]({link(x["path"])}): {x["rating"]}; {docs(x)}.')
lines+=['','## Copies and variants','','| Relationship | Locations | Evidence |','|---|---|---|']
for pair in pairs:
 if pair['decision']=='group-copy-family' or pair.get('matchingSourceHashes',0) or pair['decision']=='related-implementation-variant-kept-separate':lines.append('| '+pair['decision']+' | '+'; '.join(f'[{p}]({link(p)})' for p in pair['paths'])+f' | {pair["matchingSourceHashes"]} matching substantive-source hashes; {pair["smallerSourceOverlap"]:.0%} overlap with the smaller comparison set. '+clean(pair['basis'])+' |')
lines+=['','## Review limits and reproducible evidence','','[Machine-readable inventory](project-audit.json) contains every classified project, all alternate locations, exclusions, representative document paths and the next-batch recommendations. [Running location inventory](documentation-audit/location-inventory.json), [scan coverage](documentation-audit/scan-manifest.json), [representative readings](documentation-audit/representative-evidence.json), and [source comparison evidence](documentation-audit/duplicate-source-review.json) preserve the audit trail.','','Representative local links were checked and results are retained with each evidence file. A missing historical source anchor or a stale root README should be rechecked before following that particular exercise. The presence of a curriculum is established separately from the correctness of every statement in it. Binary files and notebooks were inventoried separately; unrelated personal documents, fixtures and branding assets were not treated as software curricula.','']
lines+=['','## Concrete documentation-quality findings','',f'- Representative review covered **{len(sampledocs):,} documents**; none changed between discovery and the representative read. Full-text screening and representative reads are distinct from line-by-line technical verification.',f'- Of **{len(checks):,} simple local file targets** sampled, **{len(missing):,} did not resolve as written**. This includes copies and stale absolute paths; it is not a whole-repository broken-link rate. Parenthesized targets and line/heading anchors were not validated by this check.', '- Saleor and Open edX contain useful source-specific exercises whose relative links can point from the wrong documentation directory. Their learning content qualifies, but navigation needs cleanup.', '- Jellyfin’s Fable index links to multiple modules that are absent locally. Its existing cartography is useful; the promised full curriculum is not present, which is why it remains partial and is in the recommended next batch.', '- MeterForge and CampusOps have meaningful specifications but mostly very short sprint outlines. FormForge also needs expanded walkthroughs. A fifteen-sprint label alone does not establish a finished course.', '- VTCode has extensive developer reference; AI Helper includes a long proposed successor specification. Those were classified as partial rather than allowing reference/specification volume to imply a complete learning system.', '- Historical PR reviews, performance claims and suggested resume stories were not independently verified. They are learning prompts, not evidence of your own work or of current production readiness.','']
text='\n'.join(lines).replace('Four independent products nested inside the organized Job Tracker folder are separate records.','The Job Tracker folder contains three other independent products and a copied Job Tracker variant. The two independent products under z3 and the sample app embedded in Code Helper are also accounted for separately.').replace('Ranked by depth and onboarding first, followed by application complexity, architecture, engineering breadth and hands-on value.','The editorial ranking prioritizes depth and onboarding, then application complexity, architecture, engineering breadth and hands-on value. Numeric screening scores in JSON are discovery aids rather than the final sort order.')
